import{_ as e,o as a,c as n,a0 as t}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"Руководство по разработке модулей","description":"","frontmatter":{},"headers":[],"relativePath":"ru_RU/guide/module.md","filePath":"ru_RU/guide/module.md"}'),l={name:"ru_RU/guide/module.md"};function o(i,s,p,d,c,r){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="introduction" tabindex="-1">Руководство по разработке модулей <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Руководство по разработке модулей {#introduction}&quot;">​</a></h1><p>KernelSU предоставляет механизм модулей, позволяющий добиться эффекта модификации системного каталога при сохранении целостности системного раздела. Этот механизм принято называть &quot;бессистемным&quot;.</p><p>Модульный механизм KernelSU практически аналогичен механизму Magisk. Если вы знакомы с разработкой модулей Magisk, то разработка модулей KernelSU очень похожа. Представление модулей ниже можно пропустить, достаточно прочитать [различия-с-magisk] (difference-with-magisk.md).</p><div class="warning custom-block"><p class="custom-block-title">МЕТАМОДУЛЬ ТРЕБУЕТСЯ ТОЛЬКО ДЛЯ МОДИФИКАЦИИ СИСТЕМНЫХ ФАЙЛОВ</p><p>KernelSU использует архитектуру <a href="./metamodule.html">метамодулей</a> для монтирования директории <code>system</code>. <strong>Только если вашему модулю нужно модифицировать файлы <code>/system</code></strong> (через директорию <code>system</code>), вам необходимо установить метамодуль (например, <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>). Другие функции модулей, такие как скрипты, правила sepolicy и system.prop, работают без метамодуля.</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>KernelSU modules support displaying interfaces and interacting with users. See the <a href="./module-webui.html">WebUI documentation</a> for additional details.</p><h2 id="конфигурация-модулеи" tabindex="-1">Конфигурация модулей <a class="header-anchor" href="#конфигурация-модулеи" aria-label="Permalink to &quot;Конфигурация модулей&quot;">​</a></h2><p>KernelSU предоставляет встроенную систему конфигурации, которая позволяет модулям хранить постоянные или временные настройки в формате ключ-значение. Подробности смотрите в <a href="./module-config.html">документации по конфигурации модулей</a>.</p><h2 id="одноразовые-скрипты" tabindex="-1">Одноразовые скрипты <a class="header-anchor" href="#одноразовые-скрипты" aria-label="Permalink to &quot;Одноразовые скрипты&quot;">​</a></h2><p>ZIP-архив модуля также может быть одноразовым скриптом, который менеджер KernelSU запускает один раз вместо установки. Подробности смотрите в <a href="./module-script.html">документации по одноразовым скриптам</a>.</p><h2 id="busybox" tabindex="-1">Busybox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;Busybox&quot;">​</a></h2><p>В комплект поставки KernelSU входит полнофункциональный бинарный файл BusyBox (включая полную поддержку SELinux). Исполняемый файл находится по адресу <code>/data/adb/ksu/bin/busybox</code>. BusyBox от KernelSU поддерживает переключаемый во время работы &quot;ASH Standalone Shell Mode&quot;. Этот автономный режим означает, что при запуске в оболочке <code>ash</code> BusyBox каждая команда будет напрямую использовать апплет внутри BusyBox, независимо от того, что задано в качестве <code>PATH</code>. Например, такие команды, как <code>ls</code>, <code>rm</code>, <code>chmod</code> будут <strong>НЕ</strong> использовать то, что находится в <code>PATH</code> (в случае Android по умолчанию это будут <code>/system/bin/ls</code>, <code>/system/bin/rm</code> и <code>/system/bin/chmod</code> соответственно), а вместо этого будут напрямую вызывать внутренние апплеты BusyBox. Это гарантирует, что скрипты всегда будут выполняться в предсказуемом окружении и всегда будут иметь полный набор команд, независимо от того, на какой версии Android они выполняются. Чтобы заставить команду <em>не</em> использовать BusyBox, необходимо вызвать исполняемый файл с полными путями.</p><p>Каждый сценарий оболочки, запущенный в контексте KernelSU, будет выполняться в оболочке BusyBox <code>ash</code> с включенным автономным режимом. Для сторонних разработчиков это касается всех загрузочных скриптов и скриптов установки модулей.</p><p>Для тех, кто хочет использовать эту возможность &quot;Автономного режима&quot; вне KernelSU, есть два способа включить ее:</p><ol><li>Установите переменной окружения <code>ASH_STANDALONE</code> значение <code>1</code><br>Пример: <code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>Переключитесь с помощью параметров командной строки:<br><code>/data/adb/ksu/bin/busybox sh -o standalone &lt;script&gt;</code></li></ol><p>Чтобы убедиться, что все последующие запуски оболочки <code>sh</code> также выполняются в автономном режиме, предпочтительным методом является вариант 1 (и это то, что KernelSU и менеджер KernelSU используют внутри), поскольку переменные окружения наследуются вплоть до дочерних процессов.</p><div class="tip custom-block"><p class="custom-block-title">отличие от Magisk</p><p>BusyBox в KernelSU теперь использует бинарный файл, скомпилированный непосредственно из проекта Magisk. **Поэтому вам не нужно беспокоиться о проблемах совместимости между скриптами BusyBox в Magisk и KernelSU, поскольку они абсолютно одинаковы!</p></div><h2 id="kernelsu-modules" tabindex="-1">Модули KernelSU <a class="header-anchor" href="#kernelsu-modules" aria-label="Permalink to &quot;Модули KernelSU {#kernelsu-modules}&quot;">​</a></h2><p>Модуль KernelSU - это папка, размещенная в каталоге <code>/data/adb/modules</code> и имеющая следующую структуру:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- Папка имеет имя с идентификатором модуля</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Идентификация модуля ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- В этом файле хранятся метаданные модуля</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Основное содержимое ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- Эта папка будет смонтирована, если skip_mount не существует</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Флаги состояния ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- Если он существует, то KernelSU НЕ будет монтировать вашу системную папку</span></span>
<span class="line"><span>│   ├── disable             &lt;--- Если модуль существует, то он будет отключен</span></span>
<span class="line"><span>│   ├── remove              &lt;--- Если модуль существует, то при следующей перезагрузке он будет удален</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Необязательные файлы ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- Этот скрипт будет выполняться в post-fs-data</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- Этот скрипт будет выполняться в сервисе late_start</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- Этот скрипт будет выполнен, когда KernelSU удалит ваш модуль</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- Свойства из этого файла будут загружены в качестве системных свойств программой resetprop</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- Дополнительные пользовательские правила sepolicy</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- Файлы .rc в этом каталоге будут добавлены в init.rc при загрузке</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Автоматически генерируется, НЕЛЬЗЯ создавать или изменять вручную ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- Символьная ссылка на $MODID/system/vendor</span></span>
<span class="line"><span>│   ├── product             &lt;--- Символьная ссылка на $MODID/system/product</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- Симлинк на $MODID/system/system_ext</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Допускается использование любых дополнительных файлов/папок ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">различия с Magisk</p><p>KernelSU не имеет встроенной поддержки Zygisk, поэтому в модуле нет содержимого, связанного с Zygisk. Однако для поддержки модулей Zygisk можно использовать <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a>. В этом случае содержимое модуля Zygisk идентично содержимому, поддерживаемому Magisk.</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p>module.prop - это конфигурационный файл модуля. В KernelSU, если модуль не содержит этого файла, он не будет распознан как модуль. Формат этого файла следующий:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (optional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (optional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (optional)</span></span></code></pre></div><ul><li><code>id</code> должно соответствовать данному регулярному выражению: <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code><br> экс: ✓ <code>a_module</code>, ✓ <code>a.module</code>, ✓ <code>module-101</code>, ✗ <code>a module</code>, ✗ <code>1_module</code>, ✗ <code>-a-module</code><br> Это <strong>уникальный идентификатор</strong> вашего модуля. Не следует изменять его после публикации.</li><li><code>versionCode</code> должен быть <strong>целым</strong>. Это используется для сравнения версий.</li><li>Другими, не упомянутыми выше, могут быть любые <strong>однострочные</strong> строки.</li><li>Обязательно используйте тип перевода строки <code>UNIX (LF)</code>, а не <code>Windows (CR+LF)</code> или <code>Macintosh (CR)</code>.</li><li><code>actionIcon</code> и <code>webuiIcon</code> — необязательные пути к изображениям, которые используются как значки по умолчанию для ярлыков действия и WebUI модуля в менеджере. Эти пути должны быть относительными к корневому каталогу модуля. Например, <code>actionIcon=icon/icon.png</code> будет интерпретирован как <code>&lt;MODDIR&gt;/icon/icon.png</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">ДИНАМИЧЕСКОЕ ОПИСАНИЕ</p><p>Поле <code>description</code> может быть динамически переопределено во время выполнения с помощью системы конфигурации модулей. Подробности см. в разделе <a href="./module-config.html#overriding-module-description">Переопределение описания модуля</a>.</p></div><h3 id="shell-scripts" tabindex="-1">Сценарии командной оболочки <a class="header-anchor" href="#shell-scripts" aria-label="Permalink to &quot;Сценарии командной оболочки {#shell-scripts}&quot;">​</a></h3><p>Чтобы понять разницу между <code>post-fs-data.sh</code> и <code>Service.sh</code>, прочитайте раздел <a href="#boot-scripts">Boot Scripts</a>. Для большинства разработчиков модулей <code>service.sh</code> должно быть достаточно, если вам нужно просто запустить загрузочный скрипт.</p><p>Во всех скриптах вашего модуля используйте <code>MODDIR=\${0%/*}</code> для получения пути к базовому каталогу вашего модуля; <strong>НЕ</strong> кодируйте жестко путь к вашему модулю в скриптах.</p><div class="tip custom-block"><p class="custom-block-title">различия с Magisk</p><p>С помощью переменной окружения KSU можно определить, выполняется ли сценарий в KernelSU или в Magisk. Если скрипт выполняется в KernelSU, то это значение будет равно true.</p></div><h3 id="system-directories" tabindex="-1">каталог <code>system</code> <a class="header-anchor" href="#system-directories" aria-label="Permalink to &quot;каталог \`system\` {#system-directories}&quot;">​</a></h3><p>После загрузки системы содержимое этого каталога будет наложено поверх раздела /system. Это означает, что:</p><div class="tip custom-block"><p class="custom-block-title">ТРЕБОВАНИЕ МЕТАМОДУЛЯ</p><p>Директория <code>system</code> монтируется только если у вас установлен метамодуль, предоставляющий функциональность монтирования (например, <code>meta-overlayfs</code>). Метамодуль обрабатывает способ монтирования модулей. См. <a href="./metamodule.html">Руководство по метамодулям</a> для получения дополнительной информации.</p></div><ol><li>Файлы с теми же именами, что и в соответствующем каталоге в системе, будут перезаписаны файлами в этом каталоге.</li><li>Папки с теми же именами, что и в соответствующем каталоге в системе, будут объединены с папками в этом каталоге.</li></ol><p>Если вы хотите удалить файл или папку в исходном каталоге системы, необходимо создать файл с тем же именем, что и файл/папка, в каталоге модуля с помощью команды <code>mknod filename c 0 0</code>. Таким образом, система overlayfs автоматически &quot;забелит&quot; этот файл, как если бы он был удален (раздел /system при этом фактически не изменится).</p><p>Вы также можете объявить в <code>customize.sh</code> переменную с именем <code>REMOVE</code>, содержащую список каталогов для выполнения операций удаления, и KernelSU автоматически выполнит команду <code>mknod &lt;TARGET&gt; c 0 0</code> в соответствующих каталогах модуля. Например:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>В приведенном выше списке будут выполнены команды <code>mknod $MODPATH/system/app/YouTuBe c 0 0</code> и <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>; при этом <code>/system/app/YouTube</code> и <code>/system/app/Bloatware</code> будут удалены после вступления модуля в силу.</p><p>Если вы хотите заменить каталог в системе, то необходимо создать каталог с тем же путем в каталоге модуля, а затем установить для этого каталога атрибут <code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code>. Таким образом, система overlayfs автоматически заменит соответствующий каталог в системе (без изменения раздела /system).</p><p>Вы можете объявить в файле <code>customize.sh</code> переменную с именем <code>REPLACE</code>, содержащую список заменяемых каталогов, и KernelSU автоматически выполнит соответствующие операции в каталоге вашего модуля. Например:</p><p>REPLACE=&quot; /system/app/YouTube /system/app/Bloatware &quot;</p><p>В этом списке будут автоматически созданы каталоги <code>$MODPATH/system/app/YouTube</code> и <code>$MODPATH/system/app/Bloatware</code>, а затем выполнены команды <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/YouTube</code> и <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/Bloatware</code>. После вступления модуля в силу каталоги <code>/system/app/YouTube</code> и <code>/system/app/Bloatware</code> будут заменены на пустые.</p><div class="tip custom-block"><p class="custom-block-title">различия с Magisk</p><p>KernelSU использует архитектуру <a href="./metamodule.html">метамодулей</a>, где монтирование делегируется подключаемым метамодулям. Официальный метамодуль <code>meta-overlayfs</code> использует OverlayFS ядра для бессистемных модификаций, в то время как Magisk использует magic mount (bind mount), встроенный непосредственно в его ядро. Оба достигают одной цели: модификация файлов <code>/system</code> без физического изменения раздела <code>/system</code>. Подход KernelSU обеспечивает большую гибкость и уменьшает поверхность обнаружения.</p></div><p>Если вы заинтересованы в использовании overlayfs, рекомендуется прочитать <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">документацию по overlayfs</a> ядра Linux.</p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>Этот файл имеет тот же формат, что и <code>build.prop</code>. Каждая строка состоит из <code>[key]=[value]</code>.</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>Если для вашего модуля требуются дополнительные патчи sepolicy, добавьте эти правила в данный файл. Каждая строка в этом файле будет рассматриваться как утверждение политики.</p><h3 id="initrc-injection" tabindex="-1">Инъекция initrc <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;Инъекция initrc {#initrc-injection}&quot;">​</a></h3><p>KernelSU предоставляет механизм для внедрения кастомных директив Android Init RC в системный <code>init.rc</code>. Это позволяет модулям регистрировать кастомные службы Android, устанавливать триггеры свойств или выполнять другие действия на языке Init без изменения системного раздела.</p><p>Во время загрузки модуль ядра KernelSU перехватывает системные вызовы <code>read()</code> и <code>fstat()</code>. Когда процесс init Android читает <code>/system/etc/init/hw/init.rc</code>, KernelSU прозрачно добавляет кастомное содержимое RC в конец файла. Процесс init анализирует эти внедренные директивы точно так же, как исходное содержимое init.rc.</p><p>На стороне пользовательского пространства ksud объединяет все файлы <code>.rc</code> из включенных модулей в один файл <code>modules.rc</code>, хранящийся в разделе <code>/metadata</code>. Этот файл автоматически пересоздается всякий раз, когда изменяется состояние модуля (установка, включение, отключение, удаление и т.д.).</p><h4 id="фаилы-initrc-модуля" tabindex="-1">Файлы initrc модуля <a class="header-anchor" href="#фаилы-initrc-модуля" aria-label="Permalink to &quot;Файлы initrc модуля&quot;">​</a></h4><p>Создайте подкаталог <code>initrc/</code> в каталоге вашего модуля и поместите туда файлы <code>.rc</code>:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Файлы должны иметь расширение <code>.rc</code>.</li><li>Пока модуль включен, все файлы <code>.rc</code> в каталоге <code>initrc/</code> будут включены (разрешение на выполнение не требуется).</li><li>Файлы обрабатываются в <strong>алфавитном порядке имен файлов</strong> внутри каталога, а модули обрабатываются в <strong>алфавитном порядке ID модулей</strong>.</li></ul></div><h4 id="общие-фаилы-initrc" tabindex="-1">Общие файлы initrc <a class="header-anchor" href="#общие-фаилы-initrc" aria-label="Permalink to &quot;Общие файлы initrc&quot;">​</a></h4><p>Помимо файлов RC на уровне модуля, вы можете поместить файлы <code>.rc</code> в глобальный каталог:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Общим файлам initrc требуется разрешение на выполнение</p><p>В отличие от каталога модуля <code>initrc/</code>, файлы в <code>/data/adb/initrc.d/</code> <strong>должны иметь права на выполнение</strong>, чтобы быть включенными. Неисполняемые файлы <code>.rc</code> будут пропущены без уведомления.</p></div><p>Общие файлы <code>initrc.d/</code> обрабатываются до любых файлов RC модулей.</p><h4 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h4><p>Вот пример файла <code>.rc</code>, который регистрирует кастомную службу Android:</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>Если этот файл помещен в <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>, он зарегистрирует службу с именем <code>myservice</code> при загрузке и запустит ее по достижении <code>sys.boot_completed=1</code>.</p><h4 id="обновление-вручную" tabindex="-1">Обновление вручную <a class="header-anchor" href="#обновление-вручную" aria-label="Permalink to &quot;Обновление вручную&quot;">​</a></h4><p>Вы можете вручную запустить пересоздание <code>modules.rc</code> с помощью следующей команды (изменения вступят в силу при следующей загрузке):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Инъекция initrc происходит очень рано в процессе загрузки (когда init читает init.rc), <strong>до</strong> выполнения post-fs-data и любых скриптов модуля.</li><li>Внедренное содержимое RC рассматривается init как часть исходного init.rc, поддерживая весь синтаксис языка Android Init (определения служб, триггеры, настройки свойств и т.д.).</li><li>Инъекция initrc <strong>недоступна</strong> в <strong>режиме late-load</strong>, поскольку хуки системных вызовов в этом режиме не устанавливаются.</li><li>Инъекцию RC модулей можно отключить, передав параметр <code>--no-custom-rc</code> при патчинге образа с помощью ksud.</li></ul></div><h2 id="module-installer" tabindex="-1">Установщик модулей <a class="header-anchor" href="#module-installer" aria-label="Permalink to &quot;Установщик модулей {#module-installer}&quot;">​</a></h2><p>Инсталлятор модуля KernelSU - это модуль KernelSU, упакованный в zip-файл, который может быть прошит в APP-менеджере KernelSU. Простейший установщик модуля KernelSU - это просто модуль KernelSU, упакованный в zip-файл.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Необязательно, более подробно позже)</span></span>
<span class="line"><span>│                                           Этот скрипт будет использоваться в update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* Остальные файлы модуля */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Модуль KernelSU НЕ поддерживается для установки в пользовательское Recovery!!!</p></div><h3 id="customizing-installation" tabindex="-1">Персонализация <a class="header-anchor" href="#customizing-installation" aria-label="Permalink to &quot;Персонализация {#customizing-installation}&quot;">​</a></h3><p>Если вам необходимо настроить процесс установки модуля, то в качестве опции вы можете создать в программе установки скрипт с именем <code>customize.sh</code>. Этот скрипт будет <em>источником</em> (не исполняться!) сценария установщика модуля после извлечения всех файлов и применения стандартных разрешений и secontext. Это очень удобно, если ваш модуль требует дополнительной настройки в зависимости от ABI устройства, или вам необходимо установить специальные разрешения/секонтекст для некоторых файлов модуля.</p><p>Если вы хотите полностью контролировать и настраивать процесс установки, объявите <code>SKIPUNZIP=1</code> в файле <code>customize.sh</code>, чтобы пропустить все шаги установки по умолчанию. При этом ваш <code>customize.sh</code> будет сам отвечать за установку.</p><p>Сценарий <code>customize.sh</code> запускается в оболочке BusyBox <code>ash</code> KernelSU с включенным &quot;Автономным режимом&quot;. Доступны следующие переменные и функции:</p><h4 id="переменные" tabindex="-1">Переменные <a class="header-anchor" href="#переменные" aria-label="Permalink to &quot;Переменные&quot;">​</a></h4><ul><li><code>KSU</code> (bool): переменная, отмечающая, что скрипт выполняется в окружении KernelSU, причем значение этой переменной всегда будет true. Ее можно использовать для различения KernelSU и Magisk.</li><li><code>KSU_VER</code> (string): строка версии текущего установленного KernelSU (например, <code>v0.4.0</code>)</li><li><code>KSU_VER_CODE</code> (int): код версии текущего установленного KernelSU в пользовательском пространстве (например, <code>10672</code>)</li><li><code>KSU_KERNEL_VER_CODE</code> (int): код версии текущей установленной KernelSU в пространстве ядра (например, <code>10672</code>)</li><li><code>BOOTMODE</code> (bool): в KernelSU всегда должно быть <code>true</code>.</li><li><code>MODPATH</code> (path): путь, по которому должны быть установлены файлы ваших модулей</li><li><code>TMPDIR</code> (path): место, где вы можете временно хранить файлы</li><li><code>ZIPFILE</code> (path): установочный zip-архив вашего модуля</li><li><code>ARCH</code> (string): архитектура процессора устройства. Значение: <code>arm</code>, <code>arm64</code>, <code>x86</code> или <code>x64</code>.</li><li><code>IS64BIT</code> (bool): <code>true</code>, если <code>$ARCH</code> имеет значение <code>arm64</code> или <code>x64</code>.</li><li><code>API</code> (int): уровень API (версия Android) устройства (например, <code>23</code> для Android 6.0)</li><li><code>KSU_UAPI_VER</code> (int): версия UAPI пользовательского пространства KernelSU (ksud) (например, <code>2</code>). Эта версия увеличивается при критических изменениях в драйвере ядра, и модули могут использовать её для проверки совместимости.</li><li><code>KSU_RUNTIME_MODE</code> (string): текущий режим работы KernelSU. Возможные значения: <code>built-in</code> (режим GKI, встроен в ядро), <code>lkm</code> (загружен как модуль ядра при запуске) или <code>late-load</code> (загружен как модуль ядра после загрузки).</li><li><code>KSU_LATE_LOAD</code> (int?): если KernelSU загружен с задержкой после загрузки системы, значение этой переменной равно <code>1</code>; в противном случае переменная не устанавливается.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>В KernelSU MAGISK_VER_CODE всегда равен 25200, а MAGISK_VER всегда равен v25.2. Пожалуйста, не используйте эти две переменные для определения того, запущен ли он на KernelSU или нет.</p></div><h4 id="functions" tabindex="-1">Функции <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Функции {#functions}&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    вывести &lt;msg&gt; на консоль</span></span>
<span class="line"><span>    Избегайте использования &#39;echo&#39;, так как он не будет отображаться в консоли пользовательского recovery</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    вывести сообщение об ошибке &lt;msg&gt; на консоль и завершить установку</span></span>
<span class="line"><span>    Избегайте использования команды &#39;exit&#39;, так как в этом случае будут пропущены шаги очистки завершения установки</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    если [context] не задан, то по умолчанию используется &quot;u:object_r:system_file:s0&quot;.</span></span>
<span class="line"><span>    Эта функция является сокращением для следующих команд:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    если [context] не задан, то по умолчанию используется &quot;u:object_r:system_file:s0&quot;.</span></span>
<span class="line"><span>    для всех файлов в &lt;directory&gt; будет вызвана команда:</span></span>
<span class="line"><span>       set_perm file owner group filepermission context</span></span>
<span class="line"><span>    для всех каталогов в &lt;directory&gt; (включая себя самого), он вызовет:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h2 id="boot-scripts" tabindex="-1">Загрузочные сценарии <a class="header-anchor" href="#boot-scripts" aria-label="Permalink to &quot;Загрузочные сценарии {#boot-scripts}&quot;">​</a></h2><p>В KernelSU скрипты делятся на два типа в зависимости от режима их работы: режим post-fs-data и режим late_start service:</p><ul><li>режим post-fs-data <ul><li>Эта стадия является БЛОКИРУЮЩЕЙ. Процесс загрузки приостанавливается до завершения выполнения или по истечении 10 секунд.</li><li>Сценарии запускаются до того, как будут смонтированы какие-либо модули. Это позволяет разработчику модулей динамически настраивать свои модули до того, как они будут смонтированы.</li><li>Этот этап происходит до запуска Zygote, что практически означает, что все в Android</li><li><strong>ПРЕДУПРЕЖДЕНИЕ:</strong> использование <code>setprop</code> приведет к блокировке процесса загрузки! Вместо этого используйте <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code>.</li><li>Запускайте скрипты в этом режиме только в случае необходимости.</li></ul></li><li>режим обслуживания late_start <ul><li>Эта стадия является НЕБЛОКИРУЮЩЕЙ. Ваш скрипт выполняется параллельно с остальным процессом загрузки.</li><li><strong>Это рекомендуемый этап для запуска большинства скриптов.</strong></li></ul></li></ul><p>В KernelSU скрипты запуска делятся на два типа по месту их хранения: общие скрипты и скрипты модулей:</p><ul><li>Общие скрипты <ul><li>Размещаются в файлах <code>/data/adb/post-fs-data.d</code> или <code>/data/adb/service.d</code>.</li><li>Выполняется только в том случае, если скрипт установлен как исполняемый (<code>chmod +x script.sh</code>)</li><li>Скрипты в <code>post-fs-data.d</code> выполняются в режиме post-fs-data, а скрипты в <code>service.d</code> - в режиме late_start service.</li><li>Модули не должны <strong>НЕ</strong> добавлять общие скрипты при установке</li></ul></li><li>Скрипты модуля <ul><li>Размещаются в отдельной папке модуля</li><li>Выполняются только в том случае, если модуль включен</li><li><code>post-fs-data.sh</code> запускается в режиме post-fs-data, а <code>service.sh</code> - в режиме late_start service.</li></ul></li></ul><p>Все загрузочные скрипты будут выполняться в оболочке BusyBox <code>ash</code> от KernelSU с включенным &quot;Автономным режимом&quot;.</p><h2 id="late-load-mode" tabindex="-1">Режим late-load <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Режим late-load {#late-load-mode}&quot;">​</a></h2><p>Помимо стандартного процесса загрузки, описанного выше, KernelSU поддерживает <strong>режим late-load</strong> для сценариев LKM (загружаемый модуль ядра). В этом режиме модуль ядра KernelSU загружается <strong>после полной загрузки системы</strong>, а не во время процесса init.</p><h3 id="когда-происходит-late-load" tabindex="-1">Когда происходит late-load? <a class="header-anchor" href="#когда-происходит-late-load" aria-label="Permalink to &quot;Когда происходит late-load?&quot;">​</a></h3><p>Late-load запускается командой <code>ksud late-load</code>. Эта команда:</p><ol><li>Определяет текущую версию KMI и загружает соответствующий <code>kernelsu.ko</code> из встроенных ресурсов.</li><li>Выполняет инициализацию модуля (правила SELinux, список разрешений, функции и т.д.), которая обычно происходит во время загрузки.</li></ol><p>Поскольку система уже полностью запущена, некоторые механизмы времени загрузки недоступны или не нужны.</p><h3 id="отличия-от-стандартнои-загрузки" tabindex="-1">Отличия от стандартной загрузки <a class="header-anchor" href="#отличия-от-стандартнои-загрузки" aria-label="Permalink to &quot;Отличия от стандартной загрузки&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Поведение</th><th style="text-align:center;">Стандартная загрузка</th><th style="text-align:center;">Режим late-load</th></tr></thead><tbody><tr><td>Модуль ядра загружен init (PID 1)</td><td style="text-align:center;">Да</td><td style="text-align:center;">Нет (загружен после загрузки)</td></tr><tr><td>Хуки kprobe ksud (execve/read/fstat/input)</td><td style="text-align:center;">Да</td><td style="text-align:center;">Пропущены</td></tr><tr><td>Обнаружение безопасного режима (клавиша громкости)</td><td style="text-align:center;">Да</td><td style="text-align:center;">Всегда отключено</td></tr><tr><td>Захват журнала загрузки (logcat/dmesg)</td><td style="text-align:center;">Да</td><td style="text-align:center;">Пропущен</td></tr><tr><td>Проверка сосуществования с Magisk</td><td style="text-align:center;">Да</td><td style="text-align:center;">Пропущена</td></tr><tr><td>Событие <code>post-fs-data</code> отправлено ядру</td><td style="text-align:center;">Да</td><td style="text-align:center;">Пропущено</td></tr><tr><td>Событие <code>boot-completed</code> отправлено ядру</td><td style="text-align:center;">Да</td><td style="text-align:center;">Установлено напрямую при инициализации</td></tr><tr><td>Скрипты <code>post-fs-data.sh</code> / <code>post-fs-data.d/</code></td><td style="text-align:center;">Да</td><td style="text-align:center;">Заменены этапом <code>late-load</code></td></tr><tr><td>Загрузка <code>system.prop</code></td><td style="text-align:center;">Да</td><td style="text-align:center;">Да</td></tr><tr><td>Монтирование OverlayFS (metamodule)</td><td style="text-align:center;">Да</td><td style="text-align:center;">Да</td></tr><tr><td>Скрипты <code>post-mount.sh</code> / <code>post-mount.d/</code></td><td style="text-align:center;">Да</td><td style="text-align:center;">Да</td></tr><tr><td>Скрипты <code>service.sh</code> / <code>service.d/</code></td><td style="text-align:center;">Да</td><td style="text-align:center;">Да</td></tr><tr><td>Скрипты <code>boot-completed.sh</code> / <code>boot-completed.d/</code></td><td style="text-align:center;">Да</td><td style="text-align:center;">Да</td></tr><tr><td>Переменная окружения <code>KSU_LATE_LOAD</code></td><td style="text-align:center;">Не установлена</td><td style="text-align:center;">Установлена в <code>1</code></td></tr><tr><td>Флаг info ядра <code>0x4</code></td><td style="text-align:center;">Не установлен</td><td style="text-align:center;">Установлен</td></tr></tbody></table><h3 id="порядок-выполнения-скриптов" tabindex="-1">Порядок выполнения скриптов <a class="header-anchor" href="#порядок-выполнения-скриптов" aria-label="Permalink to &quot;Порядок выполнения скриптов&quot;">​</a></h3><p>В режиме late-load порядок выполнения скриптов следующий:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. Загрузить kernelsu.ko (если ещё не загружен)</span></span>
<span class="line"><span>  2. Извлечь бинарные файлы, обработать обновления модулей, загрузить правила SELinux, инициализировать функции</span></span>
<span class="line"><span>  3. Выполнить скрипты late-load.d/ и скрипты late-load модулей (блокирующе)</span></span>
<span class="line"><span>  4. Загрузить system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. Выполнить скрипт монтирования metamodule (OverlayFS)</span></span>
<span class="line"><span>  6. Выполнить скрипты post-mount.d/ и post-mount.sh модулей (блокирующе)</span></span>
<span class="line"><span>  7. Выполнить скрипты service.d/ и service.sh модулей (неблокирующе)</span></span>
<span class="line"><span>  8. Выполнить скрипты boot-completed.d/ и boot-completed.sh модулей (неблокирующе)</span></span></code></pre></div><h3 id="скрипты-специфичные-для-late-load" tabindex="-1">Скрипты, специфичные для late-load <a class="header-anchor" href="#скрипты-специфичные-для-late-load" aria-label="Permalink to &quot;Скрипты, специфичные для late-load&quot;">​</a></h3><p>Модули могут предоставить скрипт <code>late-load.sh</code>, который выполняется <strong>только</strong> в режиме late-load, как замена <code>post-fs-data.sh</code>. Этот скрипт выполняется до монтирования OverlayFS, аналогично <code>post-fs-data.sh</code> в стандартном потоке.</p><p>Кроме того, общие скрипты можно размещать в <code>/data/adb/late-load.d/</code> для выполнения на этом этапе.</p><h3 id="обнаружение-режима-late-load-в-скриптах" tabindex="-1">Обнаружение режима late-load в скриптах <a class="header-anchor" href="#обнаружение-режима-late-load-в-скриптах" aria-label="Permalink to &quot;Обнаружение режима late-load в скриптах&quot;">​</a></h3><p>Модули могут определить режим late-load, проверив переменную окружения <code>KSU_LATE_LOAD</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Работа в режиме late-load</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>Это позволяет модулям соответствующим образом корректировать своё поведение, например, пропуская операции, необходимые только при ранней загрузке.</p>`,106)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
